"""Audit two OpenTSLM validation decodes without repairing either output.

The comparison is deliberately restricted to validation receipts.  It verifies that
both decodes cover exactly the same record IDs and targets before reporting output
coverage, strict usable-summary coverage, and task quality.  An invalid generation
remains an abstention; this tool only classifies why it was unusable.
"""

from __future__ import annotations

import argparse
import gzip
import hashlib
import json
from collections import Counter
from pathlib import Path

from robot_observability.comparison import KEYS, schema_valid, score
from robot_observability.metrics import parse_answer


def read_rows(path: Path) -> list[dict[str, object]]:
    opener = gzip.open if path.suffix == ".gz" else open
    with opener(path, "rt", encoding="utf-8") as handle:
        rows = [json.loads(line) for line in handle if line.strip()]
    if not rows:
        raise ValueError(f"No rows in {path}")
    return rows


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def index_rows(rows: list[dict[str, object]], label: str) -> dict[str, dict[str, object]]:
    indexed: dict[str, dict[str, object]] = {}
    for row in rows:
        record_id = row.get("record_id")
        if not isinstance(record_id, str) or not record_id:
            raise ValueError(f"{label} has a missing record_id")
        if record_id in indexed:
            raise ValueError(f"{label} repeats record_id {record_id!r}")
        if not isinstance(row.get("target"), dict):
            raise ValueError(f"{label} has no object target for {record_id!r}")
        indexed[record_id] = row
    return indexed


def read_receipt(path: Path, label: str) -> dict[str, object]:
    receipt = json.loads(path.read_text(encoding="utf-8"))
    if receipt.get("split") != "validation":
        raise ValueError(f"{label} receipt must declare split='validation'")
    for key in ("seed", "prepared_sha256", "config_sha256"):
        if key not in receipt:
            raise ValueError(f"{label} receipt lacks {key!r}")
    return receipt


def prediction_for(row: dict[str, object]) -> object:
    prediction = row.get("prediction")
    return prediction if isinstance(prediction, dict) else parse_answer(str(row.get("output", "")))


def failure_reason(row: dict[str, object]) -> str:
    """Return a mutually exclusive strict-summary outcome; never synthesize fields."""
    if not str(row.get("output", "")).strip() and not isinstance(row.get("prediction"), dict):
        return "missing_output"
    prediction = prediction_for(row)
    if not isinstance(prediction, dict):
        return "unparseable_output"
    if set(prediction) != KEYS:
        return "schema_keys"
    if not schema_valid(prediction):
        return "value_contract"
    return "usable"


def normalized_rows(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    return [{**row, "prediction": prediction_for(row)} for row in rows]


def quality(rows: list[dict[str, object]]) -> dict[str, object]:
    reasons = Counter(failure_reason(row) for row in rows)
    metrics = score(normalized_rows(rows))
    return {
        "rows": len(rows),
        "failure_counts": {reason: reasons.get(reason, 0) for reason in (
            "missing_output", "unparseable_output", "schema_keys", "value_contract", "usable"
        )},
        "failure_rates": {reason: reasons.get(reason, 0) / len(rows) for reason in (
            "missing_output", "unparseable_output", "schema_keys", "value_contract", "usable"
        )},
        "metrics": metrics,
    }


def audit(
    baseline_rows: list[dict[str, object]], candidate_rows: list[dict[str, object]],
    baseline_receipt: dict[str, object], candidate_receipt: dict[str, object],
) -> dict[str, object]:
    baseline = index_rows(baseline_rows, "baseline")
    candidate = index_rows(candidate_rows, "candidate")
    if set(baseline) != set(candidate):
        raise ValueError("Baseline and candidate do not have identical validation record IDs")
    for record_id in baseline:
        if baseline[record_id]["target"] != candidate[record_id]["target"]:
            raise ValueError(f"Target mismatch for {record_id!r}")
    if baseline_receipt["prepared_sha256"] != candidate_receipt["prepared_sha256"]:
        raise ValueError("Prepared-data hashes differ")
    record_ids = sorted(baseline)
    return {
        "split": "validation",
        "record_count": len(record_ids),
        "record_ids_sha256": hashlib.sha256(("\n".join(record_ids) + "\n").encode()).hexdigest(),
        "baseline": quality([baseline[record_id] for record_id in record_ids]),
        "candidate": quality([candidate[record_id] for record_id in record_ids]),
        "interpretation": (
            "Rows with missing, unparsable, wrong-key, or invalid-value outputs remain abstentions. "
            "This audit does not repair generations or select a checkpoint."
        ),
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--baseline", type=Path, required=True)
    parser.add_argument("--candidate", type=Path, required=True)
    parser.add_argument("--baseline-receipt", type=Path, required=True)
    parser.add_argument("--candidate-receipt", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise FileExistsError(f"Refusing to overwrite {args.output}")
    baseline_receipt = read_receipt(args.baseline_receipt, "baseline")
    candidate_receipt = read_receipt(args.candidate_receipt, "candidate")
    report = audit(read_rows(args.baseline), read_rows(args.candidate), baseline_receipt, candidate_receipt)
    report["inputs"] = {
        "baseline_sha256": sha256(args.baseline),
        "candidate_sha256": sha256(args.candidate),
        "baseline_receipt_sha256": sha256(args.baseline_receipt),
        "candidate_receipt_sha256": sha256(args.candidate_receipt),
        "baseline_receipt": baseline_receipt,
        "candidate_receipt": candidate_receipt,
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(json.dumps({"output": str(args.output), "records": report["record_count"]}, sort_keys=True))


if __name__ == "__main__":
    main()

